def min_knight_moves(pos1, pos2):
    """Compute minimum knight moves between two positions using BFS"""
    r1, c1 = pos1
    r2, c2 = pos2

    def get_neighbors(r, c):
        offsets = [(-2,-1), (-2,1), (-1,-2), (-1,2), (1,-2), (1,2), (2,-1), (2,1)]
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 11 and 0 <= nc < 11:
                yield (nr, nc)

    from collections import deque
    queue = deque([(r1, c1, 0)])
    visited = {(r1, c1)}

    while queue:
        cr, cc, dist = queue.popleft()
        if (cr, cc) == (r2, c2):
            return dist
        for nr, nc in get_neighbors(cr, cc):
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))

    return float('inf')

